std::optional<std::vector<double>> EBPathSmoother::calcSmoothedTrajectory()
{
  time_keeper_ptr_->tic(__func__);

  // solve QP
  const auto result = osqp_solver_ptr_->optimize();
  const auto optimized_points = result.primal_solution;

  const auto status = result.solution_status;

  // check status
  if (status != 1) {
    osqp_solver_ptr_->logUnsolvedStatus("[EB]");
    return std::nullopt;
  }
  const auto has_nan = std::any_of(
    optimized_points.begin(), optimized_points.end(), [](const auto v) { return std::isnan(v); });
  if (has_nan) {
    RCLCPP_WARN(logger_, "optimization failed: result contains NaN values");
    return std::nullopt;
  }

  time_keeper_ptr_->toc(__func__, "        ");
  return optimized_points;
}

OSQPResult OSQPInterface::optimize()
{
  // Run the solver on the stored problem representation.
  OSQPResult result = solve();
  return result;
}

OSQPResult OSQPInterface::solve()
{
  // Solve Problem
  int32_t exit_flag = static_cast<int32_t>(osqp_solve(m_work.get()));

  /********************
   * EXTRACT SOLUTION
   ********************/
  double * sol_x = m_work->solution->x;
  double * sol_y = m_work->solution->y;
  std::vector<double> sol_primal(sol_x, sol_x + m_param_n);
  std::vector<double> sol_lagrange_multiplier(sol_y, sol_y + m_data->m);

  int64_t status_polish = m_work->info->status_polish;
  int64_t status_solution = m_work->info->status_val;
  int64_t status_iteration = m_work->info->iter;

  // Result tuple
  OSQPResult result;

  result.primal_solution = sol_primal;
  result.lagrange_multipliers = sol_lagrange_multiplier;
  result.polish_status = static_cast<int>(status_polish);
  result.solution_status = static_cast<int>(status_solution);
  result.iteration_status = static_cast<int>(status_iteration);
  result.exit_flag = exit_flag;

  m_latest_work_info = *(m_work->info);

  return result;
}

c_int osqp_solve(OSQPWorkspace *work);


